#!/usr/bin/env node

/*
 * Purpose:
 * Audit only the locale keys that changed in the current i18n task.
 *
 * This script consumes the manifest generated by create-translation-tasks.mjs.
 * That manifest is already based on the default-locale diff, so this script
 * can verify the exact changed-key set without doing a full project-wide i18n
 * audit. Use it after translation deltas have been merged.
 *
 * The script does not translate, merge, extract, or scan unrelated keys. It
 * checks whether changed keys are present/deleted as expected, whether ICU
 * variables and rich tags match the default message, and whether non-default
 * translations have static UI-fit length warnings for compact UI.
 */

import fs from "node:fs";
import path from "node:path";
import {
  collectLocaleFiles,
  compareMessageContracts,
  findLocation,
  formatList,
  getLengthRiskWarning,
  getLocaleName,
  getMessageContract,
  getMessageValue,
  hasContractDiff,
  parseCliArgs,
  readLocaleFile,
  relativePath,
  resolveFromCwd,
  splitCsv,
} from "./lib/i18n-audit.mjs";

function printHelp() {
  console.log(`Usage:
  node skills/use-react-intl-universal/scripts/audit-changed-locale-keys.mjs --tasks tmp/i18n-translation-tasks/manifest.json --locales src/locales --default-locale en-US

Options:
  --tasks PATH              Required. manifest.json from create-translation-tasks.mjs.
  --locales PATH            Required. Directory containing locale JSON files.
  --default-locale LOCALE   Optional. Defaults to the manifest defaultLocale.
  --target-locales LIST     Optional. Comma-separated locale names to audit. By default, audits existing locale files plus task target locales.
  --json                    Print machine-readable JSON.
  --help                    Show this help.
`);
}

function readJsonFile(filePath, label) {
  try {
    return JSON.parse(fs.readFileSync(resolveFromCwd(String(filePath)), "utf8"));
  } catch (error) {
    throw new Error(`Cannot read ${label}: ${error.message}`);
  }
}

function resolveReportPath(filePath) {
  return path.isAbsolute(String(filePath))
    ? String(filePath)
    : resolveFromCwd(String(filePath));
}

function readTaskFile(taskFile) {
  const jsonPath = taskFile.jsonPath ?? taskFile.path;
  if (!jsonPath) {
    throw new Error("Task manifest contains a task file without jsonPath.");
  }

  return readJsonFile(resolveReportPath(jsonPath), `translation task file ${jsonPath}`);
}

function getLocaleFilePath(localesPath, locale) {
  return path.join(localesPath, `${locale}.json`);
}

function getTaskLocales(manifest) {
  return [...new Set((manifest.taskFiles ?? [])
    .map((taskFile) => taskFile.locale)
    .filter(Boolean))]
    .sort((a, b) => a.localeCompare(b));
}

// Translation task files repeat the same changed keys for each target locale.
// Collapse them into one changed-key map and flag manifest inconsistencies
// rather than letting duplicate task batches hide stale or conflicting input.
function collectChangedItems(manifest) {
  const itemsByKey = new Map();
  const manifestIssues = [];

  for (const taskFile of manifest.taskFiles ?? []) {
    const task = readTaskFile(taskFile);

    for (const item of task.items ?? []) {
      const existing = itemsByKey.get(item.key);
      const normalized = {
        key: item.key,
        type: item.type,
        defaultMessage: item.defaultMessage ?? null,
        previousDefaultMessage: item.previousDefaultMessage ?? null,
        source: item.source ?? null,
      };

      if (!existing) {
        itemsByKey.set(item.key, normalized);
        continue;
      }

      if (
        existing.type !== normalized.type
        || existing.defaultMessage !== normalized.defaultMessage
        || existing.previousDefaultMessage !== normalized.previousDefaultMessage
      ) {
        manifestIssues.push({
          type: "conflicting-task-item",
          key: item.key,
          message: "The same key has conflicting task metadata. Regenerate translation tasks before auditing.",
        });
      }
    }
  }

  return {
    items: [...itemsByKey.values()].sort((a, b) => a.key.localeCompare(b.key)),
    manifestIssues,
  };
}

function loadLocaleTargets(localesPath, defaultLocale, taskLocales, targetLocales) {
  const requestedTargets = new Set(targetLocales);
  const localeFilePaths = new Map();

  // Start with actual locale files so existing supported locales are audited
  // even if a translation task was generated for only one target locale.
  for (const filePath of collectLocaleFiles(localesPath)) {
    const locale = getLocaleName(filePath, localesPath);
    if (requestedTargets.size === 0 || requestedTargets.has(locale) || locale === defaultLocale) {
      localeFilePaths.set(locale, filePath);
    }
  }

  // Task target locales may point to a locale file that does not exist yet.
  // Keep those expected files in the audit so missing-file problems are visible.
  for (const locale of taskLocales) {
    if (requestedTargets.size === 0 || requestedTargets.has(locale) || locale === defaultLocale) {
      localeFilePaths.set(locale, localeFilePaths.get(locale) ?? getLocaleFilePath(localesPath, locale));
    }
  }

  if (!localeFilePaths.has(defaultLocale)) {
    localeFilePaths.set(defaultLocale, getLocaleFilePath(localesPath, defaultLocale));
  }

  return [...localeFilePaths.entries()]
    .map(([locale, filePath]) => ({ locale, filePath }))
    .sort((a, b) => (a.locale === defaultLocale ? -1 : b.locale === defaultLocale ? 1 : a.locale.localeCompare(b.locale)));
}

function readLocaleTarget(target) {
  if (!fs.existsSync(target.filePath)) {
    return {
      ...target,
      missingFile: true,
      localeFile: null,
    };
  }

  return {
    ...target,
    missingFile: false,
    localeFile: readLocaleFile(target.filePath),
  };
}

function getValueResult(localeTarget, key) {
  if (localeTarget.missingFile) {
    return {
      exists: false,
      value: undefined,
      line: null,
      contract: getMessageContract(undefined),
    };
  }

  const valueInfo = getMessageValue(localeTarget.localeFile.json, key);
  const location = valueInfo.exists
    ? findLocation(localeTarget.localeFile.propertyLocations, valueInfo.pathSegments)
    : null;

  return {
    exists: valueInfo.exists,
    value: valueInfo.value,
    line: location?.line ?? null,
    contract: getMessageContract(valueInfo.value),
  };
}

function createLocaleKeyResult({ item, localeTarget, defaultLocale, baselineContract, baselineMessage }) {
  const valueResult = getValueResult(localeTarget, item.key);
  const issues = [];
  const warnings = [];

  if (localeTarget.missingFile) {
    issues.push({
      type: "missing-locale-file",
      message: `Locale file is missing for ${localeTarget.locale}.`,
    });
    return {
      locale: localeTarget.locale,
      filePath: relativePath(localeTarget.filePath),
      line: null,
      exists: false,
      value: null,
      issues,
      warnings,
    };
  }

  if (localeTarget.localeFile.parseError) {
    issues.push({
      type: "invalid-json",
      message: localeTarget.localeFile.parseError.message,
    });
    return {
      locale: localeTarget.locale,
      filePath: relativePath(localeTarget.filePath),
      line: null,
      exists: false,
      value: null,
      issues,
      warnings,
    };
  }

  if (item.type === "deleted") {
    if (valueResult.exists) {
      issues.push({
        type: "stale-deleted-key",
        message: "Key was deleted from the default locale diff but still exists in this locale.",
      });
    }

    return {
      locale: localeTarget.locale,
      filePath: relativePath(localeTarget.filePath),
      line: valueResult.line,
      exists: valueResult.exists,
      value: valueResult.exists ? valueResult.value : null,
      issues,
      warnings,
    };
  }

  if (!valueResult.exists) {
    issues.push({
      type: "missing-locale-key",
      message: "Changed key is missing from this locale.",
    });
  } else if (!valueResult.contract.isString) {
    issues.push({
      type: "non-string-locale-message",
      message: `Message value should be a string, got ${typeof valueResult.value}.`,
    });
  } else if (localeTarget.locale === defaultLocale && item.defaultMessage != null && valueResult.value !== item.defaultMessage) {
    issues.push({
      type: "stale-task-default-message",
      message: "Current default-locale message no longer matches the translation task manifest. Regenerate translation tasks from the latest default-locale diff.",
    });
  } else if (baselineContract) {
    const diff = compareMessageContracts(baselineContract, valueResult.contract);
    if (hasContractDiff(diff)) {
      issues.push({
        type: "locale-contract-mismatch",
        message: `Contract mismatch: missing vars [${formatList(diff.missingVariables)}], extra vars [${formatList(diff.extraVariables)}], missing tags [${formatList(diff.missingTags)}], extra tags [${formatList(diff.extraTags)}].`,
        diff,
      });
    }
  }

  if (
    localeTarget.locale !== defaultLocale
    && item.type !== "deleted"
    && typeof baselineMessage === "string"
    && typeof valueResult.value === "string"
  ) {
    const lengthRisk = getLengthRiskWarning({
      key: item.key,
      locale: localeTarget.locale,
      defaultMessage: baselineMessage,
      translatedMessage: valueResult.value,
      sourceMessage: item.source,
    });

    if (lengthRisk) {
      warnings.push({
        type: "long-translation",
        message: "Static UI-fit length warning: non-default translation has greater estimated display width than the default in compact UI. Inspect the source usage before shortening text or changing layout.",
        lengthRisk,
      });
    }
  }

  return {
    locale: localeTarget.locale,
    filePath: relativePath(localeTarget.filePath),
    line: valueResult.line,
    exists: valueResult.exists,
    value: valueResult.exists ? valueResult.value : null,
    issues,
    warnings,
  };
}

function auditChangedItem(item, localeTargets, defaultLocale) {
  const defaultTarget = localeTargets.find((target) => target.locale === defaultLocale);
  const defaultValue = defaultTarget ? getValueResult(defaultTarget, item.key) : null;
  const baselineMessage = item.type === "deleted"
    ? null
    : defaultValue?.exists && typeof defaultValue.value === "string"
      ? defaultValue.value
      : item.defaultMessage;
  const baselineContract = item.type === "deleted"
    ? null
    : getMessageContract(baselineMessage);

  const localeResults = localeTargets.map((localeTarget) => createLocaleKeyResult({
    item,
    localeTarget,
    defaultLocale,
    baselineContract: baselineContract?.isString ? baselineContract : null,
    baselineMessage,
  }));

  return {
    key: item.key,
    type: item.type,
    defaultMessage: item.defaultMessage,
    previousDefaultMessage: item.previousDefaultMessage,
    source: item.source,
    baselineMessage,
    variables: baselineContract?.variables ?? [],
    richTags: baselineContract?.tags ?? [],
    locales: localeResults,
    issueCount: localeResults.reduce((count, result) => count + result.issues.length, 0),
    warningCount: localeResults.reduce((count, result) => count + result.warnings.length, 0),
  };
}

function printTextReport(report) {
  console.log(`Changed-key audit: ${report.status}`);
  console.log(`Default locale: ${report.defaultLocale}`);
  console.log(`Changed keys: ${report.changedKeyCount}`);
  console.log(`Locales: ${report.locales.join(", ") || "-"}`);
  console.log(`Issues: ${report.issueCount}`);
  console.log(`Warnings: ${report.warningCount}`);
  console.log("");

  for (const issue of report.manifestIssues) {
    console.log(`Manifest issue: ${issue.key} ${issue.message}`);
  }

  for (const keyResult of report.keys) {
    if (keyResult.issueCount === 0 && keyResult.warningCount === 0) {
      continue;
    }

    console.log(`${keyResult.key} (${keyResult.type})`);
    for (const localeResult of keyResult.locales) {
      for (const issue of localeResult.issues) {
        console.log(`  error ${localeResult.locale} ${localeResult.filePath}:${localeResult.line ?? "-"} ${issue.type}: ${issue.message}`);
      }
      for (const warning of localeResult.warnings) {
        console.log(`  warning ${localeResult.locale} ${localeResult.filePath}:${localeResult.line ?? "-"} ${warning.type}: ${warning.message}`);
      }
    }
  }
}

function main() {
  const args = parseCliArgs(process.argv.slice(2));

  if (args.help) {
    printHelp();
    return;
  }

  if (!args.tasks || !args.locales) {
    printHelp();
    process.exitCode = 2;
    return;
  }

  let manifest;
  let changedItems;
  try {
    manifest = readJsonFile(args.tasks, "translation task manifest");
    changedItems = collectChangedItems(manifest);
  } catch (error) {
    console.error(error.message);
    process.exitCode = 2;
    return;
  }

  const defaultLocale = args["default-locale"]
    ? String(args["default-locale"])
    : manifest.defaultLocale;
  if (!defaultLocale) {
    console.error("Default locale is required. Pass --default-locale or use a task manifest that contains defaultLocale.");
    process.exitCode = 2;
    return;
  }

  const localesPath = resolveFromCwd(String(args.locales));
  const targetLocales = splitCsv(args["target-locales"], []);
  const taskLocales = getTaskLocales(manifest);
  const localeTargets = loadLocaleTargets(localesPath, defaultLocale, taskLocales, targetLocales).map(readLocaleTarget);
  const keys = changedItems.items.map((item) => auditChangedItem(item, localeTargets, defaultLocale));
  const keyIssues = keys.flatMap((item) => item.locales.flatMap((locale) => locale.issues));
  const keyWarnings = keys.flatMap((item) => item.locales.flatMap((locale) => locale.warnings));
  const manifestIssueCount = changedItems.manifestIssues.length;
  const issueCount = keyIssues.length + manifestIssueCount;
  const warningCount = keyWarnings.length;
  const report = {
    status: issueCount > 0 ? "failed" : "passed",
    tasks: relativePath(resolveReportPath(args.tasks)),
    localesPath: relativePath(localesPath),
    defaultLocale,
    locales: localeTargets.map((target) => target.locale),
    changedKeyCount: keys.length,
    issueCount,
    warningCount,
    manifestIssues: changedItems.manifestIssues,
    keys,
  };

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    printTextReport(report);
  }

  if (issueCount > 0) {
    process.exitCode = 1;
  }
}

main();
